import { Router } from "express";
import { archivedTaskController, createTaskController, deleteByIdController, getAllTasksController, getTaskByIdController, updateByIdController } from "../controllers/task.controller.js";
import { isValidId } from "../middlewares/isValidId.js";
import { validateBody } from "../middlewares/validateBody.js";
import { patchSchema, postSchema } from "../schemas/validationSchemaJoi.js";
import { authMiddleware } from "../middlewares/authMiddlewares.js";
const router = Router();
router.use(authMiddleware);
router.get('/', getAllTasksController);
router.get('/:taskId', isValidId, getTaskByIdController);
router.post('/', validateBody(postSchema), createTaskController);
router.patch('/:taskId', isValidId, validateBody(patchSchema), updateByIdController);
router.patch('/:taskId/archive', isValidId, archivedTaskController);
router.delete('/:taskId', isValidId, deleteByIdController);
export default router;
